let N = 10 ; let M = 1000 ; let RR = 300 ; 

let X[] = new Array(N) ; let Y[] = new Array(N) ;
let R ; let A ; let I ; let II ; let Q ; 

function setup(){
  createCanvas(600, 600) ; background(0) ;
  fill(0,0,0,10) ; stroke(255,0,0) ;
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(-300,+300) ; Y[I] = random(-300,+300) ;
  }//I
}//setup()

function draw(){
  rect(0,0,599,599) ;
  for ( I = 0 ; I < N ; I++ ){
		for ( II = 0 ; II < M ; II++ ){
      Y[I] = (RR+Y[I])/2 ;
      R = sqrt(pow(X[I],2)+pow(Y[I],2)) ; 
      A = atan(Y[I]/X[I]) ;
      if ( X[I] < 0 ){ A = A+PI ; }  
      A = A*2 + Q ;
      X[I] = R*cos(A) ; Y[I] = R*sin(A) ;
      point(X[I]+300,Y[I]+300) ; 
		}//II
  }//let Q = 2*PI*(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/600 ;
	RR = 300-(float((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))/10) ;
}//draw()

